Read the active sheet’s cached values and evaluate C2:C3 as the conditional sum of A and B. Convert any date/datetime B to its Excel serial duration and add it to A only when both cells are non-empty. Write the resulting datetimes (or None) into C2:C3 and save.

```python
import shutil, openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
ws = wb[vws.title] if vws.title in wb.sheetnames else wb.create_sheet(vws.title)

def is_empty(v):
    if v is None:
        return True
    if isinstance(v, str):
        return v.strip() == ""
    return False

def as_datetime(v):
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    return None

def excel_duration(v):
    dt = as_datetime(v)
    if dt is not None:
        if dt < datetime(1899, 12, 31):
            base = datetime(1899, 12, 30)
        elif dt < datetime(1900, 3, 1):
            base = datetime(1899, 12, 31)
        else:
            base = datetime(1899, 12, 30)
        return dt - base

    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return timedelta(days=float(v))

    if isinstance(v, str):
        try:
            return timedelta(days=float(v.strip()))
        except Exception:
            return None

    return None

def compute(a, b):
    if (
        isinstance(a, (int, float))
        and isinstance(b, (int, float))
        and not isinstance(a, bool)
        and not isinstance(b, bool)
    ):
        return a + b

    a_dt = as_datetime(a)
    if a_dt is not None:
        dur = excel_duration(b)
        if dur is not None:
            return a_dt + dur

    if isinstance(a, (int, float)) and not isinstance(a, bool):
        dur = excel_duration(b)
        if dur is not None:
            return a + dur.total_seconds() / 86400.0

    return None

for r in range(2, 4):
    a = vws.cell(row=r, column=1).value
    b = vws.cell(row=r, column=2).value

    if is_empty(a) or is_empty(b):
        ws.cell(row=r, column=3).value = None
        print(r, "empty")
    else:
        res = compute(a, b)
        ws.cell(row=r, column=3).value = res
        print(r, repr(a), repr(b), repr(res))

wb.save(OUT)
